// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use a shell script with positional parameters to safely pass user input.
	// This completely prevents shell injection vulnerabilities without needing
	// manual and error-prone character blacklisting.
	script := `aliyun slb DescribeLoadBalancers --LoadBalancerName "$1" | jq '.LoadBalancers.LoadBalancer[]' > "$2"`

	// The arguments after the script string are assigned to $0, $1, $2, etc.
	// We pass "sh" as $0 (the shell name), followed by our actual parameters.
	cmd := exec.Command("sh", "-c", script, "sh", loadBalancerName, outputFile)

	// Capture stdout and stderr
	outputBytes, err := cmd.CombinedOutput()
	outputStr := string(outputBytes)

	if err != nil {
		return outputStr, fmt.Errorf("command failed: %w, output: %s", err, outputStr)
	}

	return outputStr, nil
}

