package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use exec.Command with discrete arguments to prevent OS Command Injection.
	// Avoid using "sh -c" with string concatenation or formatting.
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun's stdout to jq's stdin
	pipe, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmdJq.Stdin = pipe

	// Buffers to capture stdout and stderr
	var jqOut bytes.Buffer
	cmdJq.Stdout = &jqOut

	var aliyunStderr bytes.Buffer
	var jqStderr bytes.Buffer
	cmdAliyun.Stderr = &aliyunStderr
	cmdJq.Stderr = &jqStderr

	// Start the aliyun command
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Run jq (this waits for jq to finish processing)
	errJq := cmdJq.Run()

	// Wait for aliyun to finish to prevent zombie processes
	errAliyun := cmdAliyun.Wait()

	result := jqOut.String()

	// Handle errors from either command
	if errJq != nil {
		return result, fmt.Errorf("jq command failed: %w, stderr: %s", errJq, jqStderr.String())
	}
	if errAliyun != nil {
		return result, fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, aliyunStderr.String())
	}

	// Write the processed output to the specified file securely
	if err := os.WriteFile(outputFile, jqOut.Bytes(), 0644); err != nil {
		return result, fmt.Errorf("failed to write to output file: %w", err)
	}

	return result, nil
}

