package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport queries SLB information using aliyun CLI, formats it with jq,
// and exports the result to the specified output file.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Initialize commands
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Set up the pipeline: aliyun stdout -> jq stdin
	stdoutPipe, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun command: %w", err)
	}
	cmdJq.Stdin = stdoutPipe

	// Capture stderr for both commands to provide detailed error messages
	var stderrBuf bytes.Buffer
	cmdAliyun.Stderr = &stderrBuf
	cmdJq.Stderr = &stderrBuf

	// Create the output file
	file, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file %s: %w", outputFile, err)
	}
	defer file.Close()

	// Tee the jq stdout to both the output file and a buffer to return as string result
	var stdoutBuf bytes.Buffer
	cmdJq.Stdout = io.MultiWriter(file, &stdoutBuf)

	// Start the first command
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmdJq.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	// Check for errors
	if errAliyun != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, stderrBuf.String())
	}
	if errJq != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", errJq, stderrBuf.String())
	}

	return stdoutBuf.String(), nil
}

func main() {
	// Example parameters
	loadBalancerName := "my-slb-instance"
	outputFile := "output.json"

	fmt.Printf("Querying SLB: %s and exporting to %s...\n", loadBalancerName, outputFile)

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Println("Execution completed successfully.")
	fmt.Println("Result:")
	fmt.Println(result)
}

