// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use exec.Command with discrete arguments to prevent OS Command Injection.
	// This avoids the need for a shell (sh -c) and safely handles user input.
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe the stdout of aliyun command to the stdin of jq command
	pipe, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to get stdout pipe: %w", err)
	}
	cmdJq.Stdin = pipe

	// Capture stderr for both commands separately to avoid data races
	var stderrAliyun bytes.Buffer
	cmdAliyun.Stderr = &stderrAliyun

	var stderrJq bytes.Buffer
	cmdJq.Stderr = &stderrJq

	// Prepare the output file
	outFile, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()

	// Capture stdout to a buffer while simultaneously writing to the output file
	var stdoutBuf bytes.Buffer
	cmdJq.Stdout = io.MultiWriter(&stdoutBuf, outFile)

	// Start the first command
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmdJq.Start(); err != nil {
		if cmdAliyun.Process != nil {
			cmdAliyun.Process.Kill()
		}
		cmdAliyun.Wait()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to finish
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	if errAliyun != nil {
		return stdoutBuf.String(), fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, stderrAliyun.String())
	}
	if errJq != nil {
		return stdoutBuf.String(), fmt.Errorf("jq command failed: %w, stderr: %s", errJq, stderrJq.String())
	}

	return stdoutBuf.String(), nil
}

