	}
	cmd2.Stdin = pipe

	var stdoutBuf bytes.Buffer
	var stderrBuf1 bytes.Buffer
	var stderrBuf2 bytes.Buffer

	// Create the output file securely
	file, err := os.Create(outputFile)
	if err != nil {
