package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stderr of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use exec.Command directly to avoid shell injection vulnerabilities.
	// Arguments are passed safely without invoking a shell interpreter.
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	var stderrBuf bytes.Buffer
	cmd1.Stderr = &stderrBuf
	cmd2.Stderr = &stderrBuf

	// Pipe stdout of cmd1 to stdin of cmd2
	pipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create pipe: %w", err)
	}
	cmd2.Stdin = pipe

	// Open the output file safely using Go's os package
	outFile, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to open output file: %w", err)
	}
	defer outFile.Close()
	cmd2.Stdout = outFile

	// Start the first command
	if err := cmd1.Start(); err != nil {
		return stderrBuf.String(), fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmd2.Start(); err != nil {
		// Clean up the first process if the second fails to start
		if cmd1.Process != nil {
			cmd1.Process.Kill()
			cmd1.Wait()
		}
		return stderrBuf.String(), fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to finish
	err1 := cmd1.Wait()
	err2 := cmd2.Wait()

	if err1 != nil || err2 != nil {
		return stderrBuf.String(), fmt.Errorf("command failed: aliyun err: %v, jq err: %v, output: %s", err1, err2, stderrBuf.String())
	}

	return stderrBuf.String(), nil
}

