// QuerySLBAndExport queries SLB information and exports it to a file.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// We use "sh -c" to execute the target command pipeline.
	// Arguments are passed safely as $1 and $2 to prevent shell injection vulnerabilities.
	script := `aliyun slb DescribeLoadBalancers --LoadBalancerName "$1" | jq '.LoadBalancers.LoadBalancer[]' > "$2"`
	cmd := exec.Command("sh", "-c", script, "sh", loadBalancerName, outputFile)

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	if err != nil {
		return stderr.String(), fmt.Errorf("command execution failed: %w", err)
	}

	return stdout.String(), nil
}

func main() {
	// Example usage
	loadBalancerName := "my-slb-instance"
	outputFile := "output.json"

	result, err := QuerySLBAndExport(loadBalancerName, outputFile)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
		return
	}

	fmt.Println("Command executed successfully.")
	if result != "" {
		fmt.Printf("Output: %s\n", result)
	}
}

