	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	// Evaluate errors
	if errAliyun != nil {
		return stderrBuf.String(), fmt.Errorf("aliyun command failed: %w", errAliyun)
	}
	if errJq != nil {
		return stderrBuf.String(), fmt.Errorf("jq command failed: %w", errJq)
	}

	return fmt.Sprintf("Successfully exported SLB information to %s", outputFile), nil
}

func main() {
	// Example parameters
	lbName := "my-load-balancer"
	outFile := "output.json"

	result, err := QuerySLBAndExport(lbName, outFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Execution Error: %v\nStderr Output: %s\n", err, result)
