	}

	cmdAliyun.Stdout = pw
	cmdJq.Stdin = pr

	// Capture stderr for both commands
	var stderrBuf bytes.Buffer
	cmdAliyun.Stderr = &stderrBuf
	cmdJq.Stderr = &stderrBuf

	// Create the output file for redirection (equivalent to > output.json)
